import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    counter = Counter()
    for item in data:
        if isinstance(item, str):
            d = ast.literal_eval(item)
        else:
            d = item
        for key in d:
            counter[key] += 1
    return counter

import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    counter = Counter()
    for item in data:
        if isinstance(item, str):
            d = ast.literal_eval(item)
        else:
            d = item
        counter.update(d.keys())
