import re
import json
# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    if not re.match(IP_REGEX, ip_address):
        return 'Invalid IP address received'
    try:
        data = json.loads(ip_address)
        if 'ip' in data:
            return data['ip']
        else:
            return 'Invalid IP address received'
    except json.JSONDecodeError:
        return 'Invalid IP address received'

