import json
import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    data = json.loads(input_data)
    names = []
    for item in data:
        email = item.get('email')
        name = item.get('name')
        if email and name:
            names.append(name)
    if not names:
        return names
    body = "Subject: Extracted Names\n\n" + "\n".join(names)
    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
    else:
        server = smtp
    for item in data:
        email = item.get('email')
        if email:
            server.sendmail(email_address, email, body)
    if smtp is None:
        server.quit()
    return names

def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        input_data = '[]'
    try:
        data = json.loads(input_data)
    except json.JSONDecodeError:
        return []
    names = []
    recipients = []
    for item in data:
        if 'name' in item and 'email' in item:
            names.append(item['name'])
