    if names:
        message = 'Subject: Extracted Names\n\n' + '\n'.join(names)
        if smtp is None:
            server = smtplib.SMTP(smtp_server, smtp_port)
            server.starttls()
            server.login(email_address, email_password)
            for recipient in recipients:
                server.sendmail(email_address, recipient, message)
            server.quit()
        else:
            for recipient in recipients:
                smtp.sendmail(email_address, recipient, message)
    return names

def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    try:
        data = json.loads(input_data)
    except (json.JSONDecodeError, TypeError):
        return []

    names = []
    recipients = []
    if isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                name = item.get('name')
                email = item.get('email')
                if name and email:
                    names.append(name)
                    recipients.append(email)
    elif isinstance(data, dict):
        name = data.get('name')
        email = data.get('email')
        if name and email:
            names.append(name)
            recipients.append(email)

    if not names:
        return []

    message = f"Subject: Extracted Names\n\n" + "\n".join(names)

    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
        server.sendmail(email_address, recipients, message)
        server.quit()
    else:
        smtp.sendmail(email_address, recipients, message)

    return names

