import json
import re
import pandas as pd

def task_func(json_str):
    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    normalized = {}
    for key, value in data.items():
        if isinstance(value, (int, float)):
            normalized[key] = float(value) * 2.0
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2.0)
                elif isinstance(item, str):
                    nums = re.findall(r'[-+]?\d*\.?\d+', item)
                    if not nums:
                        new_list.append(item)
                    else:
                        doubled = [float(n) * 2.0 for n in nums]
                        new_list.extend(doubled if len(doubled) > 1 else doubled[0])
                else:
                    new_list.append(item)
            normalized[key] = new_list
        elif isinstance(value, str):
            # try to interpret as number first
            try:
                num = float(value)
                normalized[key] = num * 2.0
            except ValueError:
                nums = re.findall(r'[-+]?\d*\.?\d+', value)
                if not nums:
                    normalized[key] = value
                else:
                    doubled = [float(n) * 2.0 for n in nums]
                    if len(doubled) == 1:
                        normalized[key] = doubled[0]
                    else:
                        normalized[key] = doubled
        else:
            normalized[key] = value
    if not normalized:
        return pd.DataFrame()
    return pd.DataFrame(normalized, index=[0])

